string_full.source:
#42
let n = int(input())
var rep = 0
while rep < 16 {
let parts = range(n) |> map((i) => "  item${i}  ")
let cleaned = parts |> map((s) => trim(s))
let joined = join(",", cleaned)
let words = split(",", replace("item", "ITEM", joined))
let tag = repeat(3, "ab")
print("RESULT chars=${len(joined)} words=${len(words)} tag=${tag}")
rep += 1
}

